# ──────────────────────────────────────────────────────────────
# Ingest & Update Workflow
# ──────────────────────────────────────────────────────────────

def ingest_all_oblasts():
    print("🚀 Початок імпорту офіційних реєстрів Обласних військових адміністрацій (ОВА/ОДА)...")
    
    total_added = 0
    all_master_shelters = []
    
    for fname in sorted(os.listdir(REGIONS_DIR)):
        if not fname.endswith(".json"):
            continue
            
        r_code = fname[:-5]
        fpath = os.path.join(REGIONS_DIR, fname)
        with open(fpath, "r", encoding="utf-8") as fp:
            current_shelters = json.load(fp)
            
        existing_ids = {s["id"] for s in current_shelters}
        existing_names = {s["name"] for s in current_shelters}
        
        added_for_region = 0
        if r_code in OBLAST_ADMIN_SHELTERS:
            for s in OBLAST_ADMIN_SHELTERS[r_code]:
                if s["id"] not in existing_ids and s["name"] not in existing_names:
                    current_shelters.append(s)
                    existing_ids.add(s["id"])
                    existing_names.add(s["name"])
                    added_for_region += 1
                    total_added += 1

        # Sorting: Primary first, then Malls/Parkings, then others
        current_shelters.sort(key=lambda x: (0 if x.get("is_primary") else (1 if x.get("is_vehicle_accessible") else 2)))
        
        with open(fpath, "w", encoding="utf-8") as fp:
            json.dump(current_shelters, fp, ensure_ascii=False, indent=2)
            
        t1 = sum(1 for s in current_shelters if s.get("is_primary"))
        t2 = sum(1 for s in current_shelters if not s.get("is_primary"))
        all_master_shelters.extend(current_shelters)
        print(f"  ✅ {fname}: {len(current_shelters)} укриттів (Tier 1: {t1}, Tier 2: {t2}) [+ {added_for_region} нових з реєстрів ОДА]")

    # Master compile
    with open(MASTER_SEED_PATH, "w", encoding="utf-8") as fp:
        json.dump(all_master_shelters, fp, ensure_ascii=False, indent=2)

    print(f"\n🌟 УСПІШНО ОНОВЛЕНО {len(all_master_shelters)} УКРИТТІВ ПО ВСІХ РЕГІОНАХ!")
    print(f"   - Додано нових укриттів з реєстрів ОВА: {total_added}")
    print(f"   - Збережено у {MASTER_SEED_PATH}")


if __name__ == "__main__":
    ingest_all_oblasts()
